using System.Text.Json;
using FluentAssertions;
using TripCraft.Application.Workflows;

namespace TripCraft.Tests.Workflows;

public class WorkflowJsonPersistenceTests
{
    public record Snapshot(AgentWorkflowStatus Status, DateOnly Date, decimal TotalUsd);

    [Theory]
    [InlineData(null)]
    [InlineData("")]
    [InlineData(" \t\n")]
    public void Missing_json_stays_absent_in_stored_objects_and_response_elements(string? json)
    {
        WorkflowJson.Deserialize<Snapshot>(json).Should().BeNull();
        WorkflowJson.ToElement(json).Should().BeNull();
    }

    [Fact]
    public void Response_element_remains_readable_after_the_parser_document_is_disposed()
    {
        var element = WorkflowJson.ToElement("""{"days":[1,2],"approved":true}""")!.Value;

        element.GetProperty("days")[1].GetInt32().Should().Be(2);
        element.GetProperty("approved").GetBoolean().Should().BeTrue();
    }

    [Fact]
    public void Stored_snapshots_round_trip_status_dates_and_decimal_amounts()
    {
        var value = new Snapshot(AgentWorkflowStatus.PendingApproval, new(2026, 10, 2), 624.07m);
        var json = WorkflowJson.Serialize(value);

        json.Should().Contain("\"status\":\"PendingApproval\"");
        WorkflowJson.Deserialize<Snapshot>(json).Should().Be(value);
    }

    [Fact]
    public void Missing_agent_summary_defaults_to_an_object_but_explicit_json_null_is_preserved()
    {
        WorkflowJson.Raw(null).Should().Be("{}");
        WorkflowJson.Raw(default(JsonElement)).Should().Be("{}");
        using var document = JsonDocument.Parse("null");
        WorkflowJson.Raw(document.RootElement).Should().Be("null");
    }
}
